Jeremias 25 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O quarto ano de Jeoaquim correspondia a qual ano de Nabucodonosor?","o":["Primeiro ano","Terceiro ano","Quarto ano","Sétimo ano"],"c":0,"v":1,"e":"O versículo 1 diz que o quarto ano de Jeoaquim era o primeiro ano de Nabucodonosor, rei da Babilônia."},
 {"t":"multipla","p":"Como o povo reagiu à palavra que Jeremias anunciava desde a madrugada?","o":["Converteu-se","Não ouviu","Pediu um sinal","Expulsou-o da cidade"],"c":1,"v":3,"e":"No versículo 3, Jeremias diz que tem anunciado a palavra desde a madrugada, mas o povo não ouviu."},
 {"t":"multipla","p":"Como o Senhor chama Nabucodonosor neste capítulo?","o":["Meu inimigo","Meu ungido","Meu servo","Meu pastor"],"c":2,"v":9,"e":"No versículo 9, o Senhor chama Nabucodonosor, rei da Babilônia, de \"meu servo\"."},
 {"t":"multipla","p":"Por quanto tempo as nações serviriam ao rei da Babilônia?","o":["Quarenta anos","Sete anos","Cem anos","Setenta anos"],"c":3,"v":11,"e":"O versículo 11 diz que essas nações serviriam ao rei da Babilônia por setenta anos."},
 {"t":"multipla","p":"O que o Senhor mandou Jeremias tomar da sua mão?","o":["Um cálice do vinho do seu furor","Um rolo escrito","Uma vara de amendoeira","Um jugo de madeira"],"c":0,"v":15,"e":"No versículo 15, o Senhor manda Jeremias tomar o cálice do vinho do seu furor e dá-lo a beber às nações."},
 {"t":"cv","p":"O rei da Babilônia seria o último a beber do cálice.","c":true,"v":26,"e":"O versículo 26 diz que os reinos beberiam um após outro e, por fim, o rei da Babilônia."},
 {"t":"cv","p":"O Senhor diz que pouparia a cidade chamada pelo seu nome e começaria o castigo pelas nações distantes.","c":false,"v":29,"e":"No versículo 29, o Senhor diz que começa a castigar justamente na cidade chamada pelo seu nome."},
 {"t":"cv","p":"No fim do capítulo, o Senhor é comparado a um leão que desamparou a sua habitação.","c":true,"v":38,"e":"O versículo 38 diz que ele desamparou a sua habitação como um leão, porque a terra foi tornada em ruínas."}
]}

Jeremias 48 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"Por que Moabe também seria tomada?","o":["Porque fez aliança com o Egito","Porque atacou Jerusalém","Porque confiou em suas obras e em seus tesouros","Porque se recusou a pagar tributo"],"c":2,"v":7,"e":"No versículo 7, Moabe seria tomada por causa da confiança em suas obras e em seus tesouros."},
{"t":"multipla","p":"O que o texto diz sobre Moabe desde a sua juventude?","o":["Esteve tranquilo e repousou nas suas borras","Viveu em guerra constante com os vizinhos","Foi levado muitas vezes ao cativeiro","Mudou-se de um lugar para outro"],"c":0,"v":11,"e":"O versículo 11 diz que Moabe esteve tranquilo desde a juventude, repousou nas suas borras e nunca foi levado ao cativeiro."},
{"t":"multipla","p":"Moabe ficaria envergonhado de Quemos assim como Israel se envergonhou de quê?","o":["De Samaria","De Betel","De Dã","De Gilgal"],"c":1,"v":13,"e":"O versículo 13 compara a vergonha de Moabe com Quemos à vergonha de Israel com Betel, sua confiança."},
{"t":"multipla","p":"Ao mandar os moradores de Moabe deixarem as cidades, com o que o texto os manda se parecer?","o":["Com ovelhas no deserto","Com águias nos montes","Com leões na floresta","Com pombas que se aninham nos flancos do abismo"],"c":3,"v":28,"e":"O versículo 28 manda os moradores habitarem nas rochas e serem como as pombas que se aninham nos flancos do abismo."},
{"t":"multipla","p":"Segundo o texto, o que acontece com quem fugir do terror?","o":["Será morto pela espada","Fugirá para o Egito","Cairá na cova","Morrerá de fome"],"c":2,"v":44,"e":"No versículo 44, quem fugir do terror cairá na cova, e quem sair da cova será preso pela armadilha."},
{"t":"cv","p":"O capítulo declara maldito aquele que realizar a obra do Senhor de forma relaxada.","c":true,"v":10,"e":"O versículo 10 diz: Maldito aquele que realizar a obra do Senhor de forma relaxada."},
{"t":"cv","p":"O texto diz que a alegria e a festa dos campos férteis de Moabe continuariam e que as uvas seriam pisadas com júbilo.","c":false,"v":33,"e":"O versículo 33 diz o contrário: a alegria e a festa acabaram e já não pisarão uvas com júbilo."},
{"t":"cv","p":"No fim do capítulo, o Senhor diz que nos últimos dias fará retornar os prisioneiros de Moabe.","c":true,"v":47,"e":"O versículo 47 diz que, nos últimos dias, o Senhor fará retornar os prisioneiros de Moabe."}
]}

Jeremias 23 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o Senhor acusa os pastores de terem feito com as ovelhas?","o":["Dispersaram-nas e não cuidaram delas","Venderam-nas a povos estrangeiros","Levaram-nas para o templo","Abandonaram-nas no deserto"],"c":0,"v":2,"e":"No versículo 2 o Senhor diz aos pastores: \"Vós dispersastes as minhas ovelhas, as afastastes e não cuidastes delas\"."},
 {"t":"multipla","p":"Qual será o nome do Renovo justo levantado para Davi?","o":["Príncipe da Paz","O Senhor, nossa Justiça","Deus Forte","Filho de Davi"],"c":1,"v":6,"e":"O versículo 6 diz que ele será chamado \"O Senhor, nossa Justiça\"."},
 {"t":"multipla","p":"No juramento dos dias futuros, de onde o Senhor terá trazido a descendência de Israel?","o":["Da terra do Egito","Do deserto do Sinai","Da terra do Norte e de todas as terras para onde os havia arrojado","Das ilhas do mar"],"c":2,"v":8,"e":"O versículo 8 fala do Senhor que trouxe Israel \"da terra do Norte e de todas as terras para onde os havia arrojado\", em vez de lembrar a saída do Egito."},
 {"t":"multipla","p":"Em nome de quem os profetas de Samaria profetizavam?","o":["Moloque","Dagom","Astarote","Baal"],"c":3,"v":13,"e":"O versículo 13 diz que os profetas de Samaria \"profetizavam em nome de Baal\"."},
 {"t":"multipla","p":"Com que cidade o Senhor compara os profetas de Jerusalém?","o":["Sodoma","Nínive","Babel","Tiro"],"c":0,"v":14,"e":"No versículo 14 o Senhor diz que eles se tornaram para ele \"como Sodoma\", e os habitantes de Jerusalém, como Gomorra."},
 {"t":"cv","p":"O Senhor diz que mandou esses profetas e falou com eles.","c":false,"v":21,"e":"No versículo 21 o Senhor diz: \"Não mandei os profetas... eu não lhes falei; contudo, profetizaram\"."},
 {"t":"cv","p":"O Senhor compara a sua palavra a fogo e a martelo que esmiúça a penha.","c":true,"v":29,"e":"O versículo 29 pergunta: \"Não é a minha palavra fogo... e martelo que esmiúça a penha?\"."},
 {"t":"cv","p":"No fim do capítulo, o Senhor diz que se afastará do povo e da cidade que deu a eles e a seus pais.","c":true,"v":39,"e":"O versículo 39 diz: \"eis que também me afastarei de vocês e da cidade que dei a vocês e a seus pais\"."}
]}

Jeremias 15 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o Senhor, mesmo que quem se pusesse diante dele, seu coração não se inclinaria para o povo?","o":["Abraão e Davi","Moisés e Samuel","Elias e Eliseu","Noé e Jó"],"c":1,"v":1,"e":"No versículo 1, o Senhor diz que nem Moisés e Samuel fariam seu coração se inclinar para o povo."},
 {"t":"multipla","p":"Por causa de qual rei o povo seria entregue como espetáculo horrendo aos reinos da terra?","o":["Acabe, rei de Israel","Jeroboão, filho de Nebate","Manassés, filho de Ezequias","Josias, filho de Amom"],"c":2,"v":4,"e":"O versículo 4 diz que seria por causa de Manassés, filho de Ezequias, pelo que ele fez em Jerusalém."},
 {"t":"multipla","p":"As viúvas do povo se multiplicaram mais do que o quê?","o":["As estrelas do céu","As folhas do bosque","Os gafanhotos do campo","As areias do mar"],"c":3,"v":8,"e":"O versículo 8 diz que as viúvas se multiplicaram mais do que as areias do mar."},
 {"t":"multipla","p":"Ao dizer que todos o amaldiçoam, o que Jeremias afirma que nunca fez?","o":["Emprestar a juros","Roubar do vizinho","Mentir em juízo","Profanar o sábado"],"c":0,"v":10,"e":"No versículo 10, Jeremias diz que nunca emprestou a juros nem tomou emprestado a juros."},
 {"t":"multipla","p":"O que Jeremias fez com as palavras do Senhor quando as encontrou?","o":["Escondeu-as no coração","Escreveu-as num rolo","Consumiu-as","Leu-as ao rei"],"c":2,"v":16,"e":"O versículo 16 diz: Encontrei as tuas palavras e as consumi, e elas foram gozo e alegria para o seu coração."},
 {"t":"cv","p":"Jeremias diz que se assentou na roda dos zombadores.","c":false,"v":17,"e":"No versículo 17, Jeremias diz que não se assentou na roda dos zombadores e que se sentou solitário."},
 {"t":"cv","p":"Jeremias pergunta se o Senhor seria para ele como um ribeiro traiçoeiro, como águas que enganam.","c":true,"v":18,"e":"O versículo 18 traz essa pergunta, junto com a queixa de que sua dor é incessante."},
 {"t":"cv","p":"O Senhor diz que estabeleceria Jeremias como um muro forte de bronze contra o povo.","c":true,"v":20,"e":"No versículo 20, o Senhor diz que fez dele um muro forte de bronze e que o povo lutaria contra ele, mas não prevaleceria."}
]}

Jeremias 39 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde o exército dos caldeus alcançou Zedequias?","o":["No vale de Hinom","Em Betel","Nas campinas de Jericó","No deserto de Judá"],"c":2,"v":5,"e":"O versículo 5 diz que os caldeus alcançaram Zedequias nas campinas de Jericó."},
 {"t":"multipla","p":"O que o rei da Babilônia fez com os filhos de Zedequias em Ribla?","o":["Mandou matá-los à vista do pai","Levou-os presos para a Babilônia","Deixou-os em Judá com o povo pobre","Fez deles príncipes em sua corte"],"c":0,"v":6,"e":"O versículo 6 diz que o rei mandou matar os filhos de Zedequias em Ribla, à vista dele."},
 {"t":"multipla","p":"Quem levou para a Babilônia o restante do povo que ficou na cidade?","o":["Nergal-Sarezer","Nebuzaradã, chefe da guarda","Gedalias, filho de Aicão","Samgar-Nebo"],"c":1,"v":9,"e":"O versículo 9 diz que Nebuzaradã, chefe da guarda, levou o restante do povo para a Babilônia."},
 {"t":"multipla","p":"O que Nebuzaradã deu aos mais pobres que deixou em Judá?","o":["Ouro e prata","Casas na cidade","Armas para se defender","Vinhas e campos"],"c":3,"v":10,"e":"O versículo 10 diz que ele deixou alguns dos mais pobres na terra e lhes deu vinhas e campos."},
 {"t":"multipla","p":"A quem Jeremias foi entregue depois de ser retirado do átrio da guarda?","o":["A Ebed-Meleque, o etíope","A Zedequias","A Gedalias, filho de Aicão","A Nabucodonosor"],"c":2,"v":14,"e":"O versículo 14 diz que entregaram Jeremias a Gedalias, filho de Aicão, filho de Safã."},
 {"t":"cv","p":"Os príncipes do rei da Babilônia entraram em Jerusalém e se sentaram na porta central.","c":true,"v":3,"e":"O versículo 3 diz que os príncipes do rei da Babilônia entraram e se sentaram na porta central."},
 {"t":"cv","p":"Nabucodonosor ordenou que Jeremias fosse mantido preso e vigiado de perto.","c":false,"v":12,"e":"No versículo 12, a ordem foi cuidar de Jeremias com atenção, não lhe fazer mal e fazer conforme ele dissesse."},
 {"t":"cv","p":"O Senhor prometeu livrar Ebed-Meleque porque ele confiou no Senhor.","c":true,"v":18,"e":"O versículo 18 diz que Ebed-Meleque seria livrado e não cairia à espada porque confiou no Senhor."}
]}

Jeremias 33 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde Jeremias estava quando a palavra do Senhor veio a ele pela segunda vez?","o":["Encarcerado no pátio da guarda","No átrio do templo","Exilado na Babilônia","Na sua casa em Anatote"],"c":0,"v":1,"e":"O versículo 1 diz que Jeremias ainda estava encarcerado no pátio da guarda."},
 {"t":"multipla","p":"O que o Senhor promete fazer se Jeremias clamar a ele?","o":["Libertá-lo da prisão","Responder e anunciar coisas grandes e ocultas","Enviar um anjo para guardá-lo","Destruir os caldeus"],"c":1,"v":3,"e":"No versículo 3, o Senhor diz: Clama a mim e eu te responderei; anunciar-te-ei coisas grandes e ocultas."},
 {"t":"multipla","p":"O que o Senhor diz que trará sobre a cidade depois do castigo?","o":["Fome e espada","Um novo rei estrangeiro","Saúde e cura","Muros mais altos"],"c":2,"v":6,"e":"O versículo 6 diz: Eis que trarei sobre ela saúde e cura."},
 {"t":"multipla","p":"Que vozes ainda seriam ouvidas nas ruas de Jerusalém, que estavam assoladas?","o":["A voz dos guerreiros e dos reis","A voz dos profetas e dos escribas","A voz dos mercadores e dos estrangeiros","A voz do noivo e da noiva"],"c":3,"v":11,"e":"O versículo 11 lista a voz de júbilo, de alegria, a voz do noivo e a voz da noiva."},
 {"t":"multipla","p":"O que o Senhor diz que fará brotar a Davi?","o":["Uma árvore no templo","Um Renovo de justiça","Uma fonte em Jerusalém","Um exército poderoso"],"c":1,"v":15,"e":"O versículo 15 diz: farei brotar a Davi um Renovo de justiça."},
 {"t":"cv","p":"Naqueles dias, Jerusalém seria chamada pelo nome: O Senhor é a nossa justiça.","c":true,"v":16,"e":"O versículo 16 diz que este será o nome pelo qual a chamarão: O Senhor é a nossa justiça."},
 {"t":"cv","p":"O Senhor diz que a descendência de Davi e os levitas seriam poucos e fáceis de contar.","c":false,"v":22,"e":"O versículo 22 diz o contrário: seriam incontáveis como o exército dos céus e a areia do mar."},
 {"t":"cv","p":"No fim do capítulo, o Senhor diz que fará voltar o cativeiro do povo e terá compaixão deles.","c":true,"v":26,"e":"O versículo 26 termina com: farei voltar seu cativeiro e terei compaixão deles."}
]}

Jeremias 26 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde o Senhor mandou Jeremias se pôr para falar ao povo?","o":["No pátio da Casa do Senhor","Na porta do palácio do rei","Junto às muralhas de Jerusalém","Na praça do mercado"],"c":0,"v":2,"e":"No versículo 2 o Senhor diz: \"Põe-te no pátio da Casa do Senhor\"."},
 {"t":"multipla","p":"O Senhor disse que tornaria a sua casa semelhante a qual lugar, se o povo não o ouvisse?","o":["Sodoma","Samaria","Siló","Babilônia"],"c":2,"v":6,"e":"No versículo 6 o Senhor diz: \"Farei com que esta casa se torne como Siló\"."},
 {"t":"multipla","p":"O que os sacerdotes, os profetas e o povo fizeram quando Jeremias terminou de falar?","o":["Rasgaram as vestes e se arrependeram","Prenderam Jeremias e disseram que ele morreria","Expulsaram Jeremias da cidade","Levaram Jeremias direto ao rei"],"c":1,"v":8,"e":"O versículo 8 diz que eles o prenderam, dizendo: \"Certamente morrerás\"."},
 {"t":"multipla","p":"Depois de ouvir Jeremias, o que os príncipes e o povo disseram aos sacerdotes e profetas?","o":["Que Jeremias devia ser levado ao rei","Que Jeremias devia ser preso no cárcere","Que Jeremias era um falso profeta","Que Jeremias não era réu de morte"],"c":3,"v":16,"e":"No versículo 16 eles dizem: \"Este homem não é réu de morte, porque nos falou em nome do Senhor\"."},
 {"t":"multipla","p":"Que profeta do tempo de Ezequias os anciãos lembraram em defesa de Jeremias?","o":["Isaías, filho de Amoz","Elias, o tisbita","Miquéias, o morastita","Urias, filho de Semaías"],"c":2,"v":18,"e":"No versículo 18 os anciãos lembram que \"Miquéias, o morastita, profetizou nos dias de Ezequias\"."},
 {"t":"cv","p":"Quando soube que o rei queria matá-lo, o profeta Urias teve medo e fugiu para o Egito.","c":true,"v":21,"e":"O versículo 21 diz que Urias \"teve medo, fugiu e foi para o Egito\"."},
 {"t":"cv","p":"Quando trouxeram Urias do Egito, o rei Jeoaquim o deixou voltar em paz para Quiriate-Jearim.","c":false,"v":23,"e":"O versículo 23 diz que o rei mandou feri-lo à espada e lançou seu cadáver nas sepulturas da plebe."},
 {"t":"cv","p":"Aicão, filho de Safã, ficou do lado de Jeremias para que ele não fosse entregue ao povo para ser morto.","c":true,"v":24,"e":"O versículo 24 diz que a influência de Aicão estava ao lado de Jeremias, para que não o entregassem nas mãos do povo."}
]}

Jeremias 43 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que os homens soberbos disseram sobre a mensagem de Jeremias?","o":["Que era mentira","Que era verdade, mas difícil","Que precisavam de mais tempo","Que só obedeceriam ao rei"],"c":0,"v":2,"e":"No versículo 2, eles dizem a Jeremias: \"É mentira isso que você diz\"."},
 {"t":"multipla","p":"Quem eles acusaram de incitar Jeremias contra o povo?","o":["Gedalias","Baruque","Nebuzaradã","Azarias"],"c":1,"v":3,"e":"O versículo 3 diz que Baruque, filho de Nerias, incitava Jeremias para entregá-los aos caldeus."},
 {"t":"multipla","p":"Até que cidade do Egito o povo chegou?","o":["Bete-Semes","Babilônia","Tafnes","Mispá"],"c":2,"v":7,"e":"O versículo 7 diz que entraram no Egito e chegaram até Tafnes."},
 {"t":"multipla","p":"Onde Jeremias devia encaixar as pedras grandes?","o":["No altar do templo de Jerusalém","No pavimento à entrada da casa de Faraó","Às margens do rio Nilo","Na porta da cidade de Tafnes"],"c":1,"v":9,"e":"O versículo 9 manda encaixá-las na argamassa do pavimento à entrada da casa de Faraó, em Tafnes."},
 {"t":"multipla","p":"O que Nabucodonosor colocaria sobre as pedras?","o":["Um altar","Uma coluna","Uma estátua","Seu trono"],"c":3,"v":10,"e":"No versículo 10, o Senhor diz que colocaria o trono de Nabucodonosor sobre as pedras."},
 {"t":"cv","p":"Jeremias e Baruque foram levados ao Egito com o povo.","c":true,"v":6,"e":"O versículo 6 inclui o profeta Jeremias e Baruque entre os que foram levados."},
 {"t":"cv","p":"O povo foi para o Egito porque obedeceu à voz do Senhor.","c":false,"v":7,"e":"O versículo 7 diz que entraram no Egito porque não obedeceram à voz do Senhor."},
 {"t":"cv","p":"Nabucodonosor sairia do Egito derrotado.","c":false,"v":12,"e":"O versículo 12 diz que ele sairia de lá em paz."}
]}

Jeremias 46 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quem feriu o exército de Faraó-Neco junto ao Eufrates, em Carquemis?","o":["Jeoaquim, rei de Judá","Nabucodonosor, rei da Babilônia","Josias, rei de Judá","O rei da Assíria"],"c":1,"v":2,"e":"O versículo 2 diz que Nabucodonosor, rei da Babilônia, feriu o exército de Faraó-Neco no quarto ano de Jeoaquim."},
 {"t":"multipla","p":"A que o Egito é comparado quando se levanta para cobrir a terra?","o":["Ao Nilo","Ao mar","Ao rio Jordão","A um leão"],"c":0,"v":8,"e":"O versículo 8 diz que o Egito se levanta como o Nilo, e suas águas se agitam como os rios."},
 {"t":"multipla","p":"Aonde a virgem filha do Egito deve subir para tomar bálsamo?","o":["Ao Tabor","Ao Carmelo","A Gileade","A Tafnes"],"c":2,"v":11,"e":"O versículo 11 manda subir a Gileade e tomar bálsamo, mas diz que não há cura."},
 {"t":"multipla","p":"O que os soldados clamaram a respeito de Faraó?","o":["Que era um rei invencível","Que era o escolhido dos deuses","Que era um leão no deserto","Que era apenas um ruído"],"c":3,"v":17,"e":"O versículo 17 diz que clamaram que Faraó é apenas um ruído e deixou passar o tempo assinalado."},
 {"t":"multipla","p":"A que o Egito é comparado quando se anuncia a destruição que vem do norte?","o":["A uma leoa","A uma bela novilha","A uma águia","A um cedro"],"c":1,"v":20,"e":"O versículo 20 diz que o Egito é uma bela novilha, mas a destruição vem do norte."},
 {"t":"cv","p":"Os inimigos que cortam a floresta do Egito são mais numerosos do que os gafanhotos.","c":true,"v":23,"e":"O versículo 23 diz que são mais numerosos do que os gafanhotos e inumeráveis."},
 {"t":"cv","p":"Depois de ser entregue a Nabucodonosor, o Egito nunca mais seria habitado.","c":false,"v":26,"e":"O versículo 26 diz que, depois, o Egito será habitado como nos dias antigos."},
 {"t":"cv","p":"O Senhor diz que fará um fim completo de Jacó, assim como das nações.","c":false,"v":28,"e":"O versículo 28 diz que o Senhor fará um fim completo das nações, mas não de Jacó, a quem castigará com justa medida."}
]}

Jeremias 16 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"O que o Senhor proibiu Jeremias de fazer naquele lugar?","o":["Profetizar no templo","Casar-se e ter filhos","Sair da cidade","Oferecer sacrifícios"],"c":1,"v":2,"e":"Logo no início, o Senhor diz a Jeremias que não se casaria nem teria filhos nem filhas naquele lugar."},
{"t":"multipla","p":"Por que Jeremias não deveria entrar na casa do luto?","o":["Porque o Senhor retirou sua paz deste povo","Porque ficaria impuro","Porque estava doente","Porque precisava viajar"],"c":0,"v":5,"e":"O Senhor explica que retirou deste povo a sua paz, a benignidade e a misericórdia."},
{"t":"multipla","p":"O que o Senhor diz que fará cessar naquele lugar?","o":["As chuvas e as colheitas","Os sacrifícios do templo","A voz de alegria e o canto do noivo e da noiva","O comércio nas portas"],"c":2,"v":9,"e":"O Senhor dos Exércitos diz que fará cessar a voz de regozijo e de alegria, o canto do noivo e o da noiva."},
{"t":"multipla","p":"Quando o povo perguntasse qual era o seu pecado, o que Jeremias deveria responder?","o":["Que não pagaram os dízimos","Que se aliaram ao Egito","Que mataram os profetas","Que seus pais abandonaram o Senhor e serviram a deuses estrangeiros"],"c":3,"v":11,"e":"A resposta é que os pais abandonaram o Senhor, foram atrás de deuses estrangeiros e não guardaram a sua lei."},
{"t":"multipla","p":"Quem o Senhor diz que mandará primeiro para apanhar o povo?","o":["Caçadores","Pescadores","Soldados","Pastores"],"c":1,"v":16,"e":"O Senhor diz que mandará muitos pescadores e, depois, enviará muitos caçadores."},
{"t":"cv","p":"O Senhor diz que o povo se tornou melhor do que seus pais.","c":false,"v":12,"e":"O texto diz o contrário: o povo se tornou ainda pior do que seus pais, andando conforme a dureza do coração."},
{"t":"cv","p":"O Senhor promete fazer o povo voltar à terra que deu a seus pais.","c":true,"v":15,"e":"O Senhor diz que fará os filhos de Israel voltarem à sua terra, que deu a seus pais."},
